        if mode == "add_lot":
            existing = db.execute("SELECT * FROM holdings WHERE account_id = ? AND symbol = ?", (account_id, symbol)).fetchone()
            if existing is None:
                holding_id = db.execute("INSERT INTO holdings (account_id, symbol, name, type_, units, avg_cost, currency, source, purchase_date) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id", (account_id, symbol, name, type_, new_units, new_cost_per_unit, currency, source, purchase_date)).scalar()
            else:
                total_units = existing.units + new_units
                if total_units == 0:
                    merged_avg_cost = 0
                elif new_cost_per_unit is None:
                    merged_avg_cost = existing.avg_cost
                else:
                    merged_avg_cost = ((existing.units * existing.avg_cost) + (new_units * new_cost_per_unit)) / total_units
                db.execute("UPDATE holdings SET units = ?, avg_cost = ? WHERE id = ?", (total_units, merged_avg_cost, existing.id))
                holding_id = existing.id
            try:
                db.execute("INSERT INTO lots (holding_id, purchase_date, units, cost_per_unit, source) VALUES (?, ?, ?, ?, ?)", (holding_id, purchase_date, new_units, new_cost_per_unit, source))
